declare(strict_types=1);
$metrics=\Fourward\worldcup\models\PlayerBoard::RANKINGS;$current=$data['metric'];$position=$data['position'];$cards=in_array($current,['yellow_cards','red_cards'],true);$goalkeeper=$current==='saves';
?>
<div class="wc-ranking-layout"><nav class="wc-ranking-nav" aria-label="球员统计分类"><?php foreach($metrics as $key=>$label): ?><a href="<?= e($url('leaders',['metric'=>$key,'position'=>$position])) ?>" <?= $current===$key?'aria-current="page"':'' ?>><?= e($label) ?>榜</a><?php endforeach; ?></nav>
<section class="wc-panel wc-ranking-panel"><div class="wc-section-heading"><div><p class="wc-eyebrow">WORLD CUP PLAYER RANKINGS</p><h2><?= e($metrics[$current]) ?>榜</h2></div><span class="wc-muted">本届累计 · 同值并列</span></div>
<form class="wc-position-filter" method="get"><input type="hidden" name="view" value="leaders"><input type="hidden" name="metric" value="<?= e($current) ?>"><label>球员位置<select name="position"><option value="">全部位置</option><?php foreach($positions as $key=>$label): ?><option value="<?= e($key) ?>" <?= $position===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="glass-button" type="submit">筛选</button></form>
<p class="wc-muted wc-fineprint"><?= $cards?'按数据源已记录的球员领牌事件排序，包括替补席领牌；不代表完整公平竞赛分。':($goalkeeper?'扑救榜仅纳入懂球帝逐场门将统计覆盖完整的参赛门将。':'只比较已出场且该项逐场记录完整的球员，进球不含乌龙球及点球大战。') ?>点击姓名查看个人雷达与逐场数据。</p>
<?php if(!$data['items']): ?><div class="wc-empty"><h3>暂无完整可比较的记录</h3></div><?php else: ?><div class="wc-table-wrap"><table class="wc-ranking-table"><thead><tr><th>排名</th><th>球员</th><th>国家队</th><th>位置</th><th>出场</th><th><?= e($metrics[$current]) ?></th><th>场均</th></tr></thead><tbody><?php foreach($data['items'] as $r): ?><tr><td><span class="wc-rank <?= $r['rank']<=3?'wc-podium':'' ?>"><?= e($r['rank']) ?></span></td><th><a class="wc-ranking-player" href="<?= e($url('player',['id'=>$r['id']])) ?>"><?= $portrait($r) ?><?= e($r['name']) ?> ↗</a></th><td><a class="wc-standing-team" href="<?= e($url('teams',['id'=>$r['team_id']])) ?>"><?= $flag($r['code'],$r['name_zh']) ?><?= e($r['name_zh']) ?></a></td><td><?= e($positions[$r['position']]??$r['position']) ?></td><td><?= e($r['appearances']) ?></td><td class="wc-ranking-value"><?= e($number($r['totals'][$current])) ?></td><td><?= e($number($r['appearances']>0?$r['totals'][$current]/$r['appearances']:null)) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section></div>
